"""Publish a compact, explicitly scoped summary of authored regression tests.

Never copy operational conversation logs or recordings into the public report.
Input receipts are generated by the three documented live test scripts.
"""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def main():
    read = lambda name: json.loads((ROOT / 'logs' / (name + '.json')).read_text())
    live = read('speech-recovery-live')
    browser = read('speech-recovery-browser')
    suffix = read('speech-recovery-suffix-live')
    turns = []
    for row in browser['turns']:
        metrics = [e['metrics'] for e in row['events'] if e['type'] == 'pipeline_metrics'][-1]
        turns.append({
            'request': row['request'],
            'speech_complete': metrics['speech_complete'],
            'sentences': metrics['sentences'],
            'request_to_first_pcm_ms': metrics['first_audio_ms'],
            'tts_first_pcm_ms': metrics['tts_first_audio_ms'],
            'audio_motion_overlap_ms': row.get('audio_motion_overlap_ms'),
            'retries': metrics.get('tts_retries', []),
            'model': metrics['tts_actual_model'],
            'revision': metrics['tts_revision'],
            'provider': metrics['llm_actual_provider'],
        })
    tests = [{k: row[k] for k in ('text', 'passed', 'injected_pre_audio_fault',
                                  'first_pcm_ms', 'audio_s', 'wall_ms')}
             for row in live['rows']]
    output = {
        'date_utc': '2026-11-14',
        'hardware': 'Two RTX 3090 24 GiB: TTS GPU 0, Photon/Parakeet ASR GPU 1',
        'passed': bool(live['passed'] and browser['passed'] and suffix['passed']),
        'physical_microphone_test': False,
        'unit_tests': {'robby_passed': 52, 'tts_passed': 48},
        'browser_turns': turns, 'real_tts': tests,
        'isolated_browser_contracts': browser['contracts'],
        'diagrams': browser['diagrams'], 'mobile_overflow': browser['mobile_overflow'],
        'page_errors': browser['page_errors'],
        'real_suffix_recovery': {k: suffix[k] for k in (
            'passed', 'target', 'seed', 'synthetic_evidence', 'first_pcm_ms',
            'audio_s', 'suffix_recovery_observed', 'recognized_words', 'wall_ms')},
        'limitations': [
            'Small authored regression suite, not a measured deployment failure rate.',
            'Manual retry and terminal-failure text retention tested in isolated contracts.',
            'No physical microphone, noisy-room or acoustic playback validation in this run.',
            'ASR verification is fallible; suffix evaluation uses the same ASR family.',
            'The suffix test includes an extra recognized "and", not perfect WER.',
            'Rate limits, cold starts, GPU contention and retries can still add seconds.',
            'The separate five-second microphone backlog failure is not claimed fixed here.',
        ],
    }
    (ROOT/'static/speech-recovery-results.json').write_text(json.dumps(output, indent=2, ensure_ascii=False)+'\n')
    esc = html.escape
    rows = ''.join('<tr><td>'+esc(t['request'])+'</td><td>'+str(round(t['request_to_first_pcm_ms']))+
                   ' ms</td><td>'+(str(t['audio_motion_overlap_ms'])+' ms' if t['audio_motion_overlap_ms'] is not None else '—')+
                   '</td><td>'+str(t['sentences'])+' / complete</td></tr>' for t in turns)
    tts_rows = ''.join('<tr><td>'+esc(t['text'])+'</td><td>'+str(round(t['first_pcm_ms']))+
                       ' ms</td><td>'+str(round(t['audio_s'],2))+' s</td><td>'+('Client pre-admission fault' if t['injected_pre_audio_fault'] else 'No injected fault')+'</td></tr>' for t in tests)
    limits = ''.join('<li>'+esc(t)+'</li>' for t in output['limitations'])
    page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Robby — speech recovery and simultaneous stunts</title><style>
:root{color-scheme:light}body{font:17px/1.6 system-ui,sans-serif;background:#f5f7fc;color:#17243b;margin:0}main{max-width:1060px;margin:auto;padding:32px 20px}h1{line-height:1.2}h2{margin-top:2em}a{color:#1555a5}section,.card{background:white;border:1px solid #dbe2ed;border-radius:16px;padding:22px;margin:22px 0}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:12px;border-bottom:1px solid #dbe2ed;text-align:left}th{background:#eef3fc}.pass{color:#176338;font-weight:700}img{display:block;width:100%;height:auto}code{background:#eef3fc;padding:2px 4px}small{color:#4b5870}</style>
<main><nav><a href="/desk-robot/">Open Robby</a> · <a href="/desk-robot/#system-guide">System diagrams</a> · <a href="speech-recovery-results.json">JSON measurements</a></nav>
<h1>Speech that survives failures. Stunts that overlap speech.</h1><p>Verified on November 14, 2026. Robby now starts spoken spins and somersaults from the actual playback clock. Bounded speech recovery retains the complete answer and resumes only a verified unspoken suffix when possible.</p>
<p class="pass">100 targeted unit tests passed · 4 real TTS cases passed · 3 real HTTPS browser turns passed · prior truncation reproduced and recovered</p>
<section><h2>What changed</h2><p>The old four-second action deadline could finish an animation before delayed audio arrived. Spoken actions now wait for the matching reply's first played samples. Explicitly silent actions still run immediately. A final no-audio result can perform the requested motion silently.</p>
<p>A verified prefix was sometimes marked as a complete answer. The checker now identifies an exact remaining written-word suffix; only that suffix can be regenerated automatically. An uncertain continuation position does not authorize replay. After up to three attempts, the full answer remains visible with a <b>Read remaining reply</b> control. This uses the saved sentences without repeating tools or calling the language model again.</p>
<p>HTTP 429 during planning is displayed separately from speech failure. Repeated throttling can route the same Qwen model to another registered endpoint; strict endpoint pinning remains configurable. The reviewed incidents did not show a GPU OOM.</p></section>
<section><h2>Actual browser playback and rendered motion</h2><p>Small RL, single-stream generation, parallel word verification, quick reactions off. These three measured turns include the API language model; timings end at first server PCM and exclude browser playback lead. Overlap uses actual browser playback position and rendered body rotation.</p><div class="scroll"><table><thead><tr><th>Request</th><th>Request → PCM</th><th>Speech + motion overlap</th><th>Sentences spoken</th></tr></thead><tbody>'''+rows+'''</tbody></table></div>
<p>The spin and somersault both exceeded 330° of body rotation. The short spin sentence does not fill the entire six-second animation. The four-sentence reply recovered from one rejected opening. All four diagrams loaded; mobile layout had no horizontal overflow and the final browser run had no JavaScript errors.</p></section>
<section><h2>Real TTS recovery probes</h2><p>Local TTS request → first verified PCM, excluding user ASR and LLM. One connection failure was injected in the test client before admission; subsequent synthesis and ASR were real. No mock production audio or public fault-injection endpoint was used.</p><div class="scroll"><table><thead><tr><th>Target</th><th>First PCM</th><th>Output length</th><th>Fault injection</th></tr></thead><tbody>'''+tts_rows+'''</tbody></table></div><p>The final German case naturally failed its first opening check and succeeded on retry.</p></section>
<section><h2>The previously missing sentence ending</h2><p>Seed 778 reproduced the old incomplete prefix using real TTS and ASR. The checker retained “Hello, it is lovely to see you.” and requested only “We can discover something new together today.” The second attempt completed it. First PCM: <b>1,031 ms</b>; combined audio: <b>5.30 s</b>.</p><p>Final recognition: <q>Hello. It is lovely to see you and we can discover something new together today.</q> The extra “and” is a remaining transcription or generation discrepancy. This demonstrates recovery, not perfect word accuracy. The 6,992 ms test wall time includes a separate final ASR check.</p></section>
<section><h2>Reproduce and interpret the results</h2><p>See <a href="https://github.com/christophschuhmann/cartoon-face-generator/blob/main/robby/voice-assistant/SPEECH_RECOVERY.md">SPEECH_RECOVERY.md</a> for commands and policy details. Run <code>check_speech_recovery_live.py</code>, <code>check_verified_suffix_live.py</code> and <code>browser_speech_recovery_check.py</code> against an idle, warmed deployment, then <code>render_speech_recovery_report.py</code>.</p><p>The initial browser test exposed an undefined pending-action dereference; it was fixed before the passing run. Its failed receipt remains locally. Forced text retention, manual speech retry, cancellation and a twelve-second delayed playback were checked with isolated contracts. Those are distinguished from the real model turns above.</p><ul>'''+limits+'''</ul></section>
<h2>Recovery diagram</h2><a href="system-recovery.svg"><img src="system-recovery.svg" alt="Robby speech recovery flow, including retries, verified suffixes, retained answers and playback-timed actions"></a>
<p><small>Only authored regression requests and reviewed measurements are published. No visitor recordings, identity embeddings or credentials are included.</small></p></main></html>'''
    (ROOT/'static/speech-recovery.html').write_text(page)
    print(json.dumps({'passed': output['passed'], 'browser_turns': len(turns), 'real_tts': len(tests)}))


if __name__ == '__main__':
    main()
